insert into public.glossary_entries (id, name, steps, notes, is_builtin) values ('d3820d40-17ac-48b8-ad32-c0524cf97c98', 'Ballistic Kettlebell Row', ARRAY['Hinge at your hips with a flat back.', 'Hold the kettlebell with one hand.', 'Brace your core.', 'Pull the kettlebell explosively toward your ribs.', 'Lower it under control.', 'Repeat.']::text[], '{}', true)
on conflict (id) do update set name = excluded.name, steps = excluded.steps, notes = excluded.notes, is_builtin = true;

insert into public.glossary_entries (id, name, steps, notes, is_builtin) values ('cf2f801a-9575-4d46-a762-fcf39b33f652', 'Clean & Press (2 hands)', ARRAY['Start with the kettlebell on the floor.', 'Hinge at your hips and grab the handle with both hands.', 'Use a strong hip drive to bring the kettlebell to chest height.', 'Brace your core.', 'Press the kettlebell overhead.', 'Lower it under control.']::text[], '{}', true)
on conflict (id) do update set name = excluded.name, steps = excluded.steps, notes = excluded.notes, is_builtin = true;

insert into public.glossary_entries (id, name, steps, notes, is_builtin) values ('68726aaf-9be3-4247-ac8e-47a3766efdf1', 'Crunch', ARRAY['Lie on your back with your knees bent.', 'Keep your feet on the floor.', 'Brace your abdomen.', 'Lift your head and upper shoulders slightly off the floor.', 'Lower yourself slowly.', 'Repeat.']::text[], '{}', true)
on conflict (id) do update set name = excluded.name, steps = excluded.steps, notes = excluded.notes, is_builtin = true;

insert into public.glossary_entries (id, name, steps, notes, is_builtin) values ('8cc6484d-bb5a-47ed-ad8b-9a09c3d1870c', 'Dead Bug', ARRAY['Lie on your back.', 'Extend your arms toward the ceiling.', 'Bend your knees to approximately 90 degrees.', 'Keep your lower back pressed toward the floor.', 'Slowly lower one arm and the opposite leg.', 'Return to the starting position.', 'Repeat on the other side.']::text[], '{}', true)
on conflict (id) do update set name = excluded.name, steps = excluded.steps, notes = excluded.notes, is_builtin = true;

insert into public.glossary_entries (id, name, steps, notes, is_builtin) values ('40069d20-5f58-4a75-a7b7-e1e799e94326', 'Goblet Squat', ARRAY['Hold the kettlebell at chest height with both hands.', 'Keep your elbows tucked.', 'Sit your hips back and down between your knees.', 'Keep your chest up.', 'Drive through your heels to stand tall.']::text[], '{}', true)
on conflict (id) do update set name = excluded.name, steps = excluded.steps, notes = excluded.notes, is_builtin = true;

insert into public.glossary_entries (id, name, steps, notes, is_builtin) values ('36e9ef84-7024-40c0-a2ca-9c89d6ad4e2b', 'Goblet Squat → 2 Lunges', ARRAY['Hold the kettlebell in the goblet position.', 'Perform 1 goblet squat.', 'Return to standing.', 'Step one leg backward and perform 1 reverse lunge.', 'Return to standing.', 'Step the other leg backward and perform 1 reverse lunge.', 'Return to standing and repeat.']::text[], ARRAY['One sequence consists of:', 'Sequence: squat → right lunge → left lunge']::text[], true)
on conflict (id) do update set name = excluded.name, steps = excluded.steps, notes = excluded.notes, is_builtin = true;

insert into public.glossary_entries (id, name, steps, notes, is_builtin) values ('a89b7214-c5ea-4ade-a2d0-f71a3836dee8', 'Kettlebell Deadlift', ARRAY['Stand with your feet about hip-width apart.', 'Place the kettlebell between your feet.', 'Hinge at your hips while keeping your back flat.', 'Grab the handle with both hands.', 'Drive through your heels.', 'Squeeze your glutes as you stand tall.', 'Lower the kettlebell by pushing your hips back.']::text[], ARRAY['Use slower lowering if needed.']::text[], true)
on conflict (id) do update set name = excluded.name, steps = excluded.steps, notes = excluded.notes, is_builtin = true;

insert into public.glossary_entries (id, name, steps, notes, is_builtin) values ('a1b4d5cd-fa19-4cfe-aa96-c2a864799f71', 'Kettlebell Row', ARRAY['Hinge at your hips with a flat back.', 'Hold the kettlebell handle with both hands.', 'Pull it toward your lower ribs.', 'Keep your shoulders down.', 'Keep your core braced.', 'Lower it under control.']::text[], ARRAY['Pause briefly at the top of each rep.']::text[], true)
on conflict (id) do update set name = excluded.name, steps = excluded.steps, notes = excluded.notes, is_builtin = true;

insert into public.glossary_entries (id, name, steps, notes, is_builtin) values ('0451b48a-b0b7-4333-a78e-0360d44abeee', 'Kettlebell Swing', ARRAY['Place the kettlebell slightly in front of you.', 'Hinge at your hips with a slight bend in your knees.', 'Grab the kettlebell with both hands.', 'Hike it backward between your legs.', 'Snap your hips forward powerfully.', 'Let the kettlebell float to about chest height.', 'Keep your arms relaxed.', 'Let the kettlebell fall naturally into the next hip hinge.']::text[], ARRAY['The movement should be driven primarily by your hips rather than your arms.', 'Keep each rep explosive and technically clean. Do not chase maximum reps.']::text[], true)
on conflict (id) do update set name = excluded.name, steps = excluded.steps, notes = excluded.notes, is_builtin = true;

insert into public.glossary_entries (id, name, steps, notes, is_builtin) values ('e4b1f735-3048-47ec-aaaf-c65dcbf5f09e', 'Kneeling Push Up', ARRAY['Start on your knees.', 'Place your hands slightly wider than shoulder width.', 'Keep your body in a straight line from knees to shoulders.', 'Lower your chest toward the floor.', 'Press through your palms to return to the start.']::text[], ARRAY['Use these only if full push-ups are not clean yet.']::text[], true)
on conflict (id) do update set name = excluded.name, steps = excluded.steps, notes = excluded.notes, is_builtin = true;

insert into public.glossary_entries (id, name, steps, notes, is_builtin) values ('1d42eddb-17ed-42ae-a892-8fc546414b34', 'Push Up', ARRAY['Start in a high plank.', 'Place your hands slightly wider than shoulder width.', 'Keep your body in a straight line from head to heels.', 'Lower your chest toward the floor.', 'Press through your palms to return to the start.']::text[], ARRAY['If these are easy, use a slower lowering, a pause at the bottom, or elevate your feet.']::text[], true)
on conflict (id) do update set name = excluded.name, steps = excluded.steps, notes = excluded.notes, is_builtin = true;

insert into public.glossary_entries (id, name, steps, notes, is_builtin) values ('6549b0b7-416d-4e39-a418-378b17075b62', 'Reverse Goblet Lunge', ARRAY['Hold the kettlebell at chest height with both hands.', 'Keep your elbows tucked.', 'Step one leg backward.', 'Lower both knees toward roughly 90 degrees.', 'Drive through your front heel to return to standing.', 'Repeat with the opposite leg.']::text[], '{}', true)
on conflict (id) do update set name = excluded.name, steps = excluded.steps, notes = excluded.notes, is_builtin = true;

insert into public.glossary_entries (id, name, steps, notes, is_builtin) values ('5caba21c-f42f-439f-aea8-b62bf14d05b0', 'Single Arm Kettlebell Clean', ARRAY['Start with the kettlebell on the floor slightly in front of you.', 'Hinge at your hips and grab the handle with one hand.', 'Use a powerful hip drive to bring the kettlebell upward.', 'Guide it toward your shoulder.', 'Allow it to rotate smoothly around your wrist.', 'Finish in the rack position at shoulder height.']::text[], '{}', true)
on conflict (id) do update set name = excluded.name, steps = excluded.steps, notes = excluded.notes, is_builtin = true;

insert into public.glossary_entries (id, name, steps, notes, is_builtin) values ('c517203b-e692-4fea-abab-7639edb2968c', 'Single Arm Kettlebell Clean & Press', ARRAY['Clean the kettlebell into the rack position at your shoulder.', 'Brace your core.', 'Press the kettlebell overhead until your arm is fully extended.', 'Lower it under control to the rack position.', 'Repeat.', 'Perform the clean and press on one side.', 'Bring the kettlebell down under control.', 'Switch hands.', 'Perform the next repetition on the other side.', 'Continue alternating.']::text[], ARRAY['For the alternating version:']::text[], true)
on conflict (id) do update set name = excluded.name, steps = excluded.steps, notes = excluded.notes, is_builtin = true;

insert into public.glossary_entries (id, name, steps, notes, is_builtin) values ('ab5872e4-83be-469e-a464-0f09d0398386', 'Single Arm Kettlebell Row', ARRAY['Hinge forward with a neutral spine.', 'Grab the kettlebell with one hand.', 'Support yourself with your free hand if needed.', 'Pull the kettlebell toward your hip.', 'Keep your elbow close to your body.', 'Lower it under control.']::text[], ARRAY['Prefer this controlled row unless you are confident with ballistic rows.']::text[], true)
on conflict (id) do update set name = excluded.name, steps = excluded.steps, notes = excluded.notes, is_builtin = true;

insert into public.glossary_entries (id, name, steps, notes, is_builtin) values ('18d567b8-128e-4878-aa0a-a098b49b22fd', 'Suitcase Hold', ARRAY['Stand tall holding the kettlebell by your side in one hand.', 'Keep your shoulders level.', 'Brace your core.', 'Avoid leaning to either side.', 'Maintain an upright posture.']::text[], ARRAY['For a 60-second interval:', '30 seconds right', '30 seconds left']::text[], true)
on conflict (id) do update set name = excluded.name, steps = excluded.steps, notes = excluded.notes, is_builtin = true;

insert into public.glossary_entries (id, name, steps, notes, is_builtin) values ('bce42bea-bf2e-4b1c-a75a-6bab3d9c175c', 'Suitcase March', ARRAY['Hold the kettlebell at your side in one hand.', 'Stand tall and brace your core.', 'March slowly in place.', 'Lift one knee at a time.', 'Keep your shoulders and hips level.', 'Avoid leaning toward or away from the kettlebell.', 'Switch hands halfway through the interval.']::text[], ARRAY['For a 35-second interval:', 'Switch hands halfway', 'Alternate which side starts each round.']::text[], true)
on conflict (id) do update set name = excluded.name, steps = excluded.steps, notes = excluded.notes, is_builtin = true;

insert into public.glossary_entries (id, name, steps, notes, is_builtin) values ('bf3c1b15-9fcf-429e-a953-63653f4003bc', 'Thruster (2 hands)', ARRAY['Hold the kettlebell at chest height with both hands.', 'Squat down while keeping your chest tall.', 'Drive upward explosively.', 'Use the momentum from your legs to press the kettlebell overhead.', 'Lower it back to chest height.', 'Repeat.']::text[], '{}', true)
on conflict (id) do update set name = excluded.name, steps = excluded.steps, notes = excluded.notes, is_builtin = true;

